const relatedBooks = `-- name: RelatedBooks :many
SELECT        CAST(EXISTS(SELECT 1 FROM cover_assets ca WHERE ca.book_id=b.id) OR EXISTS(SELECT 1 FROM covers cv WHERE cv.book_id=b.id AND cv.legacy_path LIKE '/covers/%' AND (cv.legacy_path LIKE '%.jpg' OR cv.legacy_path LIKE '%.jpeg' OR cv.legacy_path LIKE '%.png' OR cv.legacy_path LIKE '%.webp' OR cv.legacy_path LIKE '%.gif')) AS INTEGER) AS has_cover,
b.id,b.title,b.author,b.tag1,b.tag2,b.word_count,b.chapter_count,b.has_content,s.score,
 CAST(CASE WHEN ?1<>'' AND b.author=?1 THEN 2 ELSE 1 END AS INTEGER) AS relevance,
 CAST(CASE WHEN ?2>0 AND b.word_count>0 THEN abs(1.0*b.word_count/?2-1) ELSE 100 END AS REAL) AS distance
FROM books b JOIN rating_snapshots s ON s.book_id=b.id
WHERE b.id<>?3 AND b.status='APPROVED' AND b.has_content=1
 AND (b.title<>?4 OR b.author<>?5)
 AND ((?1<>'' AND b.author=?1)
   OR (?6<>'' AND (b.tag1=?6 OR b.tag2=?6))
   OR (?7<>'' AND (b.tag1=?7 OR b.tag2=?7)))
ORDER BY relevance DESC, distance ASC, s.score DESC, b.id DESC LIMIT 6
`

type RelatedBooksParams struct {
	Author         interface{}
	Words          interface{}
	BookID         int64
	Title          string
	OriginalAuthor string
	Tag1           interface{}
	Tag2           interface{}
}

type RelatedBooksRow struct {
	HasCover     int64
	ID           int64
	Title        string
	Author       string
	Tag1         string
	Tag2         string
	WordCount    int64
	ChapterCount int64
	HasContent   int64
	Score        float64
	Relevance    int64
	Distance     float64
}

// Recommendations use local metadata only. Unknown identities cannot create
// matches, and absent candidates remain an empty list instead of random books.
func (q *Queries) RelatedBooks(ctx context.Context, arg RelatedBooksParams) ([]RelatedBooksRow, error) {
	rows, err := q.db.QueryContext(ctx, relatedBooks,
		arg.Author,
		arg.Words,
		arg.BookID,
		arg.Title,
		arg.OriginalAuthor,
		arg.Tag1,
		arg.Tag2,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RelatedBooksRow{}
	for rows.Next() {
		var i RelatedBooksRow
		if err := rows.Scan(
			&i.HasCover,
			&i.ID,
			&i.Title,
			&i.Author,
			&i.Tag1,
			&i.Tag2,
			&i.WordCount,
			&i.ChapterCount,
			&i.HasContent,
			&i.Score,
			&i.Relevance,
			&i.Distance,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

